import{_ as d,o as a,c as e,a2 as r}from"./chunks/framework.BW2T23B9.js";const p=JSON.parse('{"title":"本地数据与隐私","description":"","frontmatter":{},"headers":[],"relativePath":"guide/data-and-privacy.md","filePath":"guide/data-and-privacy.md","lastUpdated":null}'),i={name:"guide/data-and-privacy.md"};function l(o,t,h,n,c,s){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="本地数据与隐私" tabindex="-1">本地数据与隐私 <a class="header-anchor" href="#本地数据与隐私" aria-label="Permalink to &quot;本地数据与隐私&quot;">​</a></h1><p>Turna 的默认运行模型是单人、本地、离线。不存在必需的账号、云后端、排行榜或推送依赖。启用外部 AI 或卡片网络访问时，数据边界发生变化，必须由用户显式配置。</p><h2 id="数据分类" tabindex="-1">数据分类 <a class="header-anchor" href="#数据分类" aria-label="Permalink to &quot;数据分类&quot;">​</a></h2><table tabindex="0"><thead><tr><th>数据</th><th>默认位置</th><th>真理源 / 派生</th></tr></thead><tbody><tr><td>课程内容</td><td>bundle JSON</td><td>真理源</td></tr><tr><td>课程运行缓存</td><td>drift SQLite</td><td>派生</td></tr><tr><td>Lesson 进度</td><td>本地数据库 / 偏好</td><td>用户状态</td></tr><tr><td>SRS 状态与历史</td><td>本地数据库</td><td>用户状态</td></tr><tr><td>Official Anki Collection</td><td>本地应用存储</td><td>导入数据与用户状态</td></tr><tr><td>Anki 媒体</td><td>本地文件</td><td>导入资产</td></tr><tr><td>设置</td><td>本地偏好</td><td>用户配置</td></tr><tr><td>AI 凭据</td><td>原生安全存储或会话内</td><td>敏感配置</td></tr><tr><td>AI 缓存</td><td>内存或本地缓存</td><td>可再生成</td></tr><tr><td>日志与健康摘要</td><td>本地</td><td>诊断数据</td></tr></tbody></table><h2 id="不自动上传的数据" tabindex="-1">不自动上传的数据 <a class="header-anchor" href="#不自动上传的数据" aria-label="Permalink to &quot;不自动上传的数据&quot;">​</a></h2><ul><li>完整课程数据库。</li><li>复习历史。</li><li>错题正文。</li><li>Anki 卡片正文和媒体。</li><li>API key。</li><li>原始日志正文。</li></ul><p>AI 请求会发送完成当前功能所需的文本和上下文。关闭个性化后，不附加学习者画像、旧会话和错题历史。</p><h2 id="外部网络入口" tabindex="-1">外部网络入口 <a class="header-anchor" href="#外部网络入口" aria-label="Permalink to &quot;外部网络入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入口</th><th>启用条件</th><th>发送内容</th></tr></thead><tbody><tr><td>AI Provider</td><td>用户配置并发起请求</td><td>Prompt、必要上下文、附件</td></tr><tr><td>Anki 卡片远程资源</td><td>用户允许卡片网络策略</td><td>模板发起的远程请求</td></tr><tr><td>代码和课程更新</td><td>用户主动执行</td><td>标准下载请求</td></tr></tbody></table><p>Anki 卡片网络默认完全离线。AI 与卡片网络是独立开关。</p><h2 id="导出与报告" tabindex="-1">导出与报告 <a class="header-anchor" href="#导出与报告" aria-label="Permalink to &quot;导出与报告&quot;">​</a></h2><p>脱敏系统报告可以包含版本、数据库结构版本、平台、WebView/TTS 能力、错误等级和关键高级设置。报告不得包含：</p><ul><li>原始错误正文。</li><li>API key。</li><li>卡片或课程正文。</li><li>用户输入。</li><li>AI 对话。</li></ul><p>报告在分享前提供预览，并从内存文件导出。</p><h2 id="删除语义" tabindex="-1">删除语义 <a class="header-anchor" href="#删除语义" aria-label="Permalink to &quot;删除语义&quot;">​</a></h2><p>“清缓存”只处理可再生成缓存。“清除 AI 学习数据”“删除牌组”“清除应用数据”是不同操作，必须分别确认。删除操作不得使用含糊的统一按钮。</p><h2 id="备份原则" tabindex="-1">备份原则 <a class="header-anchor" href="#备份原则" aria-label="Permalink to &quot;备份原则&quot;">​</a></h2><p>应用数据是本地数据。卸载、系统清理或设备故障可能造成丢失。导入源文件、课程 JSON 和需要保留的导出文件应放在应用私有目录之外的受控备份位置。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/docs/developer/local-data">本地数据模型</a></li><li><a href="/docs/guide/ai-configuration">配置 AI</a></li><li><a href="/docs/guide/anki-rendering">卡片渲染与网络隔离</a></li></ul>',20)])])}const b=d(i,[["render",l]]);export{p as __pageData,b as default};
